{
  "format": "decision-lab-workflow/1",
  "id": "review-first-shipment",
  "version": "1.0.1",
  "title": "Review a first shipment",
  "question": "Can we meet this delivery commitment, and what should we verify before committing money?",
  "description": "Review one delivery commitment, the actual transportation records and complete alternative arrangements. If a timely verification could change the choice, compare its feasible responses with reserving now. Finish with a reviewable proposal and its unresolved conditions.",
  "metadata": {
    "profile": {
      "format": "first-shipment-review.profile/1",
      "id": "first-shipment-review",
      "version": "1.0.0",
      "title": "Review a first shipment",
      "status": "contract-proof",
      "scope": "One shipment, two complete arrangements, one uncertain transportation registration claim and one observation before arrangement selection.",
      "applicability": [
        "One fixed order revision and receipt commitment",
        "A complete finite directory of relevant operating states and arrangements",
        "One report followed by selection of a complete static arrangement"
      ],
      "separationOfLabor": {
        "templateAuthor": "Own the finite evidence, static commitment and two-stage learning reasoning contracts.",
        "moduleAuthor": "Define the supported transportation states, registration requirement, observation meanings, complete arrangement constraints and consequence meaning.",
        "workflowAuthor": "Declare exact scope, time, unit and result mappings; specify reviewed handoffs without duplicating operating rules.",
        "caseWorker": "Supply actual records, accepted commitment, current quotes, resource and permission registries, probability assessments and incurred expenses.",
        "reviewer": "Accept a particular current result and basis before its findings enter a dependent analysis."
      },
      "appModels": {
        "evidence": "evidence.model.json",
        "planning": "planning.model.json",
        "learning": "learning.model.json"
      },
      "units": {
        "money": {
          "currency": "USD",
          "minorUnit": "cent",
          "scale": 100
        },
        "time": {
          "unit": "minute",
          "origin": "2026-11-17T00:00:00-06:00",
          "offsetMinutes": -360
        },
        "quantity": "case"
      },
      "semanticScope": {
        "keys": [
          "orderId",
          "orderRevision",
          "recipient",
          "shipDate",
          "profileVersion"
        ],
        "registrationAdditionalKey": "shipPoint",
        "directShipPointId": "SP-A",
        "reservationCutoff": {
          "shared": "commitment.reserveBy",
          "planning": "case.parameters.reservationDeadline",
          "learning": "case.actions[].deadline",
          "meaning": "Latest time to choose and reserve an arrangement."
        },
        "receiptDeadline": {
          "shared": "commitment.receiveBy",
          "planning": "case.parameters.receiptDeadline",
          "meaning": "Latest customer receipt; never used as the learning decision cutoff."
        },
        "actionReady": {
          "planning": "case.parameters.actionReady",
          "meaning": "Current time for acting now, or actual prospective report availability plus reviewed response duration for a learning branch."
        }
      },
      "stateProjection": {
        "evidenceTable": "state-details",
        "stateIdColumn": "stateId",
        "planningScenarioTable": "scenarios",
        "planningScenarioStateColumn": "stateId",
        "learningStateIds": [
          "registered",
          "not_registered"
        ],
        "deduplicateBy": "stateId",
        "mappings": [
          {
            "evidenceStateId": "registered",
            "planningStateId": "registered",
            "learningStateId": "registered",
            "transportationRegistered": true
          },
          {
            "evidenceStateId": "not_registered",
            "planningStateId": "not_registered",
            "learningStateId": "not_registered",
            "transportationRegistered": false
          }
        ],
        "conditions": [
          "Evaluation coverage is complete.",
          "Evidence has at least one compatible explanation.",
          "Scope keys and profile version match exactly.",
          "The shipment lead accepts the exact evidence result and basis hashes."
        ],
        "unknownPolicy": "Retain every mapped state compatible with the reviewed records. A probability of zero does not remove a mandatory operating state."
      },
      "responseEligibility": {
        "source": "planning.plans[].scenarios[]",
        "actionKey": "choices.arrangement",
        "stateKey": "inputs.stateId",
        "passedKey": "passed",
        "conditions": [
          "Planning admission and plan-scenario coverage are complete.",
          "Each action maps to one whole static arrangement.",
          "For each possible report, choose an action only if every mandatory requirement passes in every operating state that report leaves possible.",
          "Reassess packing, release, reservation, receipt, expense, cash and authority at the branch action-ready time with its one verification fee.",
          "A high payoff never overrides operational ineligibility."
        ],
        "immediateActionReady": "planning.currentTime",
        "reportActionReady": "investigation.reportMinute + commitment.responseMinutes"
      },
      "observations": {
        "exactRegistryVerification": {
          "id": "exact-registry-verification",
          "reports": [
            {
              "id": "confirmed_registered",
              "possibleStateIds": [
                "registered"
              ],
              "likelihoods": {
                "registered": 1,
                "not_registered": 0
              }
            },
            {
              "id": "confirmed_not_registered",
              "possibleStateIds": [
                "not_registered"
              ],
              "likelihoods": {
                "registered": 0,
                "not_registered": 1
              }
            },
            {
              "id": "no_result",
              "possibleStateIds": [],
              "likelihoods": {
                "registered": 0,
                "not_registered": 0
              }
            }
          ],
          "basis": "Stipulated perfectly accurate report for this bounded contract example. No reliability claim about an actual service is made."
        },
        "actualReportRule": "A hypothetical branch is never appended to evidence. A performed investigation adds its source, actual observation, incurred fee and a new case revision; affected app results require reassessment.",
        "noisyRegistryVerification": {
          "id": "noisy-registry-verification",
          "basis": "Hypothetical 90% classification accuracy; either report remains logically possible in either transportation state.",
          "reports": [
            {
              "id": "confirmed_registered",
              "possibleStateIds": [
                "registered",
                "not_registered"
              ],
              "likelihoods": {
                "registered": 0.9,
                "not_registered": 0.1
              }
            },
            {
              "id": "confirmed_not_registered",
              "possibleStateIds": [
                "registered",
                "not_registered"
              ],
              "likelihoods": {
                "registered": 0.1,
                "not_registered": 0.9
              }
            },
            {
              "id": "no_result",
              "possibleStateIds": [],
              "likelihoods": {
                "registered": 0,
                "not_registered": 0
              }
            }
          ]
        },
        "missingRegistryVerification": {
          "id": "missing-registry-verification",
          "basis": "Hypothetical 90% exact response and 10% no response in either state; a missing response establishes neither registration nor nonregistration.",
          "reports": [
            {
              "id": "confirmed_registered",
              "possibleStateIds": [
                "registered"
              ],
              "likelihoods": {
                "registered": 0.9,
                "not_registered": 0
              }
            },
            {
              "id": "confirmed_not_registered",
              "possibleStateIds": [
                "not_registered"
              ],
              "likelihoods": {
                "registered": 0,
                "not_registered": 0.9
              }
            },
            {
              "id": "no_result",
              "possibleStateIds": [
                "registered",
                "not_registered"
              ],
              "likelihoods": {
                "registered": 0.1,
                "not_registered": 0.1
              }
            }
          ]
        }
      },
      "informationStates": [
        "unanswered",
        "unknown",
        "awaiting-review",
        "accepted"
      ],
      "handoffRules": {
        "acceptedMeaning": "A reviewer accepted this exact result hash and the case, module and evidence basis hashes. Changing a dependency makes that acceptance stale.",
        "noEvidencePossibilities": "Block the planning handoff; an inconsistent or empty basis never establishes a feasible plan.",
        "incompleteAssessment": "Preserve partial status and require further assessment; never interpret unvisited cases as failures or successes.",
        "missingProbabilities": "Planning remains available. Learning remains unavailable until a separate reviewed probability assessment is supplied.",
        "zeroProbabilityState": "Retain the state for mandatory operational eligibility; probability weight controls expected value only."
      },
      "feeAccounting": {
        "field": "case.parameters.studyFee",
        "chargeId": "verification-fee",
        "meaning": "Exactly one prospective fee in a hypothetical branch or exactly one incurred fee after an actual observation. The complete arrangement quote excludes it.",
        "paymentField": "case.parameters.studyFeeAt",
        "budgetAndCashEffect": "Planning checks both total expense and peak cash including this fee. Learning subtracts the fee once when comparing the investigation policy with acting now.",
        "authority": "The declared study-purchase grant and cap are independent of the expense ceiling. Calculated benefit is not purchase permission."
      },
      "reassessment": [
        {
          "changes": [
            "arrangements.costMinor",
            "authority.budgetMinor",
            "authority.cashLimitMinor",
            "authority.studyPurchaseGrant",
            "authority.studyPurchaseCapMinor",
            "operations",
            "planning.preparationMinutes",
            "planning.releaseMinutes",
            "commitment.quantity"
          ],
          "invalidates": [
            "planning",
            "learning",
            "proposal"
          ]
        },
        {
          "changes": [
            "evidence.observations",
            "evidence.sources",
            "scope",
            "planning.currentTime"
          ],
          "invalidates": [
            "evidence",
            "planning",
            "learning",
            "proposal"
          ]
        },
        {
          "changes": [
            "learning.probabilityAssessment",
            "learning.investigations.observationModelId"
          ],
          "invalidates": [
            "learning",
            "proposal"
          ]
        },
        {
          "changes": [
            "learning.investigations.feeMinor",
            "learning.investigations.reportAvailableAt",
            "learning.investigations.reportMinute",
            "commitment.responseMinutes"
          ],
          "invalidates": [
            "prospective-planning-contexts",
            "learning",
            "proposal"
          ]
        },
        {
          "changes": [
            "commitment.reserveBy",
            "commitment.receiveBy",
            "arrangements.departureMinute",
            "arrangements.travelMinutes",
            "planning.receiptOpen",
            "planning.receiptClose"
          ],
          "invalidates": [
            "planning",
            "learning",
            "proposal"
          ]
        }
      ],
      "boundaries": [
        "Contract fixtures and explicit handoff proof; not a workflow runner or generic adapter language.",
        "The slow report arrives after reservation, so it cannot inform this two-stage reservation decision. A policy that reserves before a late report requires a future multi-stage policy capability.",
        "Final shipment release, external booking, actual study purchase and multi-user approval execution remain separate actions."
      ]
    },
    "presentation": {
      "version": 1,
      "groups": [
        {
          "id": "commitment",
          "label": "Commitment",
          "question": "What must arrive, where, and by when?",
          "subtabs": [
            {
              "id": "shipment",
              "label": "Shipment",
              "question": "Which complete shipment are we reviewing?",
              "questionIds": [
                "scope",
                "receive-at",
                "quantity",
                "quantity-unit"
              ]
            },
            {
              "id": "deadlines",
              "label": "Deadlines & windows",
              "question": "What are the decision cutoff, delivery deadline and receiving window?",
              "questionIds": [
                "current-time",
                "reservation-cutoff",
                "receipt-deadline",
                "response-time",
                "receipt-open",
                "receipt-close"
              ]
            }
          ]
        },
        {
          "id": "arrangements",
          "label": "Arrangements",
          "question": "Which complete arrangements can we consider?",
          "subtabs": [
            {
              "id": "options",
              "label": "Available options",
              "question": "What is included in each complete shipment arrangement?",
              "questionIds": [
                "arrangements"
              ]
            },
            {
              "id": "preparation",
              "label": "Preparation",
              "question": "Who will pack and release the shipment, and how much time do they need?",
              "questionIds": [
                "preparation-time",
                "release-time",
                "packing-actor",
                "release-actor"
              ]
            },
            {
              "id": "funding",
              "label": "Funding & purchase authority",
              "question": "What spending, cash and verification purchase authority is available?",
              "questionIds": [
                "authority"
              ]
            }
          ]
        },
        {
          "id": "records",
          "label": "Prerequisites & records",
          "question": "What do the records establish about the arrangements?",
          "subtabs": [
            {
              "id": "prerequisites",
              "label": "Operating prerequisites",
              "question": "Which capabilities, calendars, resources and permissions are recorded?",
              "questionIds": [
                "operations"
              ]
            },
            {
              "id": "observations",
              "label": "Observed records",
              "question": "Which actual records apply to this shipment and direct ship point?",
              "questionIds": [
                "evidence-scope",
                "evidence-id",
                "observations",
                "sources",
                "incurred-fees"
              ]
            },
            {
              "id": "verification",
              "label": "Further verification",
              "question": "Should we compare another check, using which reviewed assumptions and offers?",
              "questionIds": [
                "learning-requested",
                "probabilities",
                "investigations"
              ]
            }
          ]
        },
        {
          "id": "planning",
          "label": "Planning results",
          "question": "Which complete arrangements meet the recorded requirements?",
          "kind": "evaluations",
          "subtabs": []
        },
        {
          "id": "next-action",
          "label": "Next action",
          "question": "What can we propose, and what remains to be reviewed or approved?",
          "kind": "brief",
          "subtabs": []
        }
      ],
      "questions": {
        "scope": {
          "type": "object",
          "label": "Shipment identity and units",
          "fields": {
            "orderId": {
              "type": "string",
              "label": "Order ID"
            },
            "orderRevision": {
              "type": "string",
              "label": "Order revision"
            },
            "recipient": {
              "type": "string",
              "label": "Receiving location"
            },
            "shipDate": {
              "type": "string",
              "label": "Ship date",
              "placeholder": "YYYY-MM-DD"
            },
            "profileVersion": {
              "type": "string",
              "label": "Shipment profile version"
            },
            "directShipPointId": {
              "type": "string",
              "label": "Direct ship point"
            },
            "backupShipPointId": {
              "type": "string",
              "label": "Backup ship point"
            },
            "currency": {
              "type": "string",
              "label": "Currency"
            },
            "amountUnit": {
              "type": "string",
              "label": "Money unit"
            },
            "timeUnit": {
              "type": "string",
              "label": "Time unit"
            },
            "timeOrigin": {
              "type": "string",
              "label": "Time origin",
              "placeholder": "2026-11-17T12:00:00-06:00",
              "help": "Include the date, time and UTC offset."
            }
          }
        },
        "receive-at": {
          "type": "string",
          "label": "Receiving location"
        },
        "reservation-cutoff": {
          "type": "string",
          "label": "Reservation cutoff",
          "placeholder": "2026-11-17T12:00:00-06:00",
          "help": "Include the date, time and UTC offset."
        },
        "receipt-deadline": {
          "type": "string",
          "label": "Receipt deadline",
          "placeholder": "2026-11-17T12:00:00-06:00",
          "help": "Include the date, time and UTC offset."
        },
        "response-time": {
          "type": "number",
          "label": "Review and response duration (minutes)"
        },
        "quantity": {
          "type": "number",
          "label": "Committed quantity"
        },
        "quantity-unit": {
          "type": "string",
          "label": "Quantity unit"
        },
        "current-time": {
          "type": "number",
          "label": "Current time (minute from time origin)",
          "integer": true
        },
        "preparation-time": {
          "type": "number",
          "label": "Packing duration (minutes)"
        },
        "release-time": {
          "type": "number",
          "label": "Release duration (minutes)"
        },
        "packing-actor": {
          "type": "string",
          "label": "Packing actor"
        },
        "release-actor": {
          "type": "string",
          "label": "Release actor"
        },
        "receipt-open": {
          "type": "number",
          "label": "Receiving window opens (minute from time origin)",
          "integer": true
        },
        "receipt-close": {
          "type": "number",
          "label": "Receiving window closes (minute from time origin)",
          "integer": true
        },
        "arrangements": {
          "type": "array",
          "label": "Complete arrangements",
          "items": {
            "type": "object",
            "label": "Record",
            "fields": {
              "id": {
                "type": "string",
                "label": "Arrangement ID",
                "options": [
                  "direct",
                  "backup"
                ]
              },
              "shipPointId": {
                "type": "string",
                "label": "Ship point"
              },
              "costMinor": {
                "type": "number",
                "label": "Complete arrangement quote (USD cents)",
                "integer": true
              },
              "departureMinute": {
                "type": "number",
                "label": "Departure (minute from time origin)",
                "integer": true
              },
              "travelMinutes": {
                "type": "number",
                "label": "Travel duration (minutes)"
              },
              "arrivalAt": {
                "type": "string",
                "label": "Offered arrival",
                "placeholder": "2026-11-17T12:00:00-06:00",
                "help": "Include the date, time and UTC offset."
              },
              "capacity": {
                "type": "number",
                "label": "Capacity (shipment quantity unit)"
              }
            }
          }
        },
        "authority": {
          "type": "object",
          "label": "Budget, cash and purchase authority",
          "fields": {
            "budgetMinor": {
              "type": "number",
              "label": "Expense limit (USD cents)",
              "integer": true
            },
            "cashLimitMinor": {
              "type": "number",
              "label": "Available cash (USD cents)",
              "integer": true
            },
            "studyPurchaseCapMinor": {
              "type": "number",
              "label": "Verification purchase limit (USD cents)",
              "integer": true
            },
            "studyPurchaseGrant": {
              "type": "object",
              "label": "Verification purchase grant",
              "fields": {
                "id": {
                  "type": "string",
                  "label": "Grant ID"
                },
                "actor": {
                  "type": "string",
                  "label": "Authorized purchaser"
                },
                "orderId": {
                  "type": "string",
                  "label": "Order ID"
                },
                "orderRevision": {
                  "type": "string",
                  "label": "Order revision"
                },
                "recipient": {
                  "type": "string",
                  "label": "Receiving location"
                },
                "shipDate": {
                  "type": "string",
                  "label": "Ship date",
                  "placeholder": "YYYY-MM-DD"
                },
                "profileVersion": {
                  "type": "string",
                  "label": "Shipment profile version"
                },
                "action": {
                  "type": "string",
                  "label": "Permitted action"
                },
                "validFrom": {
                  "type": "number",
                  "label": "Grant valid from (minute from time origin)",
                  "integer": true
                },
                "validUntil": {
                  "type": "number",
                  "label": "Grant valid until (exclusive) (minute from time origin)",
                  "integer": true
                },
                "ceilingMinor": {
                  "type": "number",
                  "label": "Grant ceiling (USD cents)",
                  "integer": true
                }
              },
              "nullable": true,
              "presenceLabel": "A verification purchase grant is recorded"
            }
          }
        },
        "operations": {
          "type": "object",
          "label": "Operating prerequisites",
          "fields": {
            "capabilities": {
              "type": "array",
              "label": "Recorded capabilities",
              "items": {
                "type": "object",
                "label": "Record",
                "fields": {
                  "actor": {
                    "type": "string",
                    "label": "Actor"
                  },
                  "action": {
                    "type": "string",
                    "label": "Action"
                  }
                }
              }
            },
            "calendars": {
              "type": "array",
              "label": "Working calendars",
              "items": {
                "type": "object",
                "label": "Record",
                "fields": {
                  "actor": {
                    "type": "string",
                    "label": "Actor"
                  },
                  "start": {
                    "type": "number",
                    "label": "Available from (minute from time origin)",
                    "integer": true
                  },
                  "end": {
                    "type": "number",
                    "label": "Available until (exclusive) (minute from time origin)",
                    "integer": true
                  }
                }
              }
            },
            "resources": {
              "type": "array",
              "label": "Resource capacities",
              "items": {
                "type": "object",
                "label": "Record",
                "fields": {
                  "id": {
                    "type": "string",
                    "label": "Resource ID"
                  },
                  "capacity": {
                    "type": "number",
                    "label": "Capacity"
                  }
                }
              }
            },
            "bookings": {
              "type": "array",
              "label": "Existing resource bookings",
