                    "label": "Order revision"
                  },
                  "recipient": {
                    "type": "string",
                    "label": "Receiving location"
                  },
                  "shipDate": {
                    "type": "string",
                    "label": "Ship date",
                    "placeholder": "YYYY-MM-DD"
                  },
                  "profileVersion": {
                    "type": "string",
                    "label": "Shipment profile version"
                  },
                  "start": {
                    "type": "number",
                    "label": "Valid from (minute from time origin)",
                    "integer": true
                  },
                  "end": {
                    "type": "number",
                    "label": "Valid until (exclusive) (minute from time origin)",
                    "integer": true
                  }
                }
              }
            }
          }
        },
        "evidence-scope": {
          "type": "object",
          "label": "Scope of transportation records",
          "fields": {
            "orderId": {
              "type": "string",
              "label": "Order ID"
            },
            "orderRevision": {
              "type": "string",
              "label": "Order revision"
            },
            "recipient": {
              "type": "string",
              "label": "Receiving location"
            },
