          "id": "shipment-review-evidence",
          "version": 1,
          "name": "Review ship-point registration",
          "description": "Determine whether the reviewed records establish transportation registration for this shipment, ship point, date and profile. A portal listing is compatible with registered and unregistered transportation states. Actual registry observations constrain those states; hypothetical future reports are not evidence.",
          "source": "# Canonical Decision Lab data. Rules are data, never executable code.\nformat: evidence-review/1\nmodule:\n  id: first-shipment-registration-evidence\n  version: \"1.0.0\"\n  title: Review ship-point registration\n  metadata:\n    catalog:\n      domain:\n        id: order-fulfillment\n        label: Order fulfillment\n        description: \"Review delivery commitments, operating prerequisites and shipment arrangements.\"\n      useCase:\n        id: review-first-shipment\n        label: Review a first shipment\n        description: Review one shipment before committing money to an arrangement.\n  description: \"Determine whether the reviewed records establish transportation registration for this shipment, ship point, date and profile. A portal listing is compatible with registered and unregistered transportation states. Actual registry observations constrain those states; hypothetical future reports are not evidence.\"\n  question: \"Do these records establish that SP-A is transportation-registered for this shipment?\"\n  boundary: \"One order revision, receiving location, direct ship point, effective date and profile version. The two declared transportation states exhaust the supported example. Accepted source observations are assumed accurate for this scope. Contradictory registry observations have no compatible explanation. No probabilities, spending authority or physical booking follow from this finding.\"\n  assumptions: [The declared state directory is complete for this scoped claim. Portal presence does not imply transportation registration., An actual registry observation reports transportation registration accurately for the exact supplied scope., The shipment owner reviews the scope and source records before accepting an evaluation for a planning handoff., \"Admissible explanations are possibilities, not probability weights. Multiple explanations must be deduplicated when projected to operating state identifiers.\"]\n  parameters:\n    - id: currentTime\n      type: integer\n      min: 0\n      default: 480\n      label: Current shipment review time\n  relations:\n    - id: scope\n      source: basis\n      columns:\n        - id: id\n          type: string\n        - id: orderId\n          type: string\n        - id: orderRevision\n          type: string\n        - id: recipient\n          type: string\n        - id: shipDate\n          type: string\n        - id: profileVersion\n          type: string\n        - id: shipPoint\n          type: string\n      key: [id]\n    - id: source\n      source: basis\n      columns:\n        - id: id\n          type: string\n        - id: scope\n          type: string\n          references:\n            relation: scope\n            column: id\n        - id: kind\n          type: string\n        - id: observedAt\n          type: integer\n        - id: description\n          type: string\n      key: [id]\n    - id: state\n      source: basis\n      columns:\n        - id: id\n          type: string\n        - id: scope\n          type: string\n          references:\n            relation: scope\n            column: id\n        - id: portalListed\n          type: boolean\n        - id: registered\n          type: boolean\n      key: [id]\n    - id: portalObservation\n      source: evidence\n      columns:\n        - id: id\n          type: string\n        - id: scope\n          type: string\n          references:\n            relation: scope\n            column: id\n        - id: value\n          type: boolean\n        - id: sourceId\n          type: string\n          references:\n            relation: source\n            column: id\n      key: [id]\n    - id: registryObservation\n      source: evidence\n      columns:\n        - id: id\n          type: string\n        - id: scope\n          type: string\n          references:\n            relation: scope\n            column: id\n        - id: value\n          type: boolean\n        - id: sourceId\n          type: string\n          references:\n            relation: source\n            column: id\n      key: [id]\n    - id: selectedState\n      source: assignment\n      columns:\n        - id: stateId\n          type: string\n          references:\n            relation: state\n            column: id\n      key: [stateId]\n    - id: stateDetails\n      source: derived\n      columns:\n        - id: stateId\n          type: string\n        - id: scope\n          type: string\n        - id: portalListed\n          type: boolean\n        - id: registered\n          type: boolean\n      key: [stateId]\n    - id: recordMismatch\n      source: derived\n      columns:\n        - id: observation\n          type: string\n        - id: field\n          type: string\n        - id: expected\n          type: boolean\n        - id: recorded\n          type: boolean\n      key: [observation]\n  generation:\n    - id: SELECT.TRANSPORTATION.STATE\n      label: Consider each supported transportation state\n      relation: selectedState\n      from:\n        relation: state\n        column: id\n      min: 1\n      max: 1\n  rules:\n    - id: DESCRIBE.TRANSPORTATION.STATE\n      head:\n        relation: stateDetails\n        args: [\"?state\", \"?scope\", \"?portal\", \"?registered\"]\n      body:\n        - relation: selectedState\n          args: [\"?state\"]\n        - relation: state\n          args: [\"?state\", \"?scope\", \"?portal\", \"?registered\"]\n    - id: PORTAL.RECORD.MISMATCH\n      head:\n        relation: recordMismatch\n        args: [\"?observation\", portal_listed, \"?expected\", \"?recorded\"]\n      body:\n        - relation: portalObservation\n          args: [\"?observation\", \"?scope\", \"?recorded\", \"?source\"]\n        - relation: stateDetails\n          args: [\"?state\", \"?scope\", \"?expected\", \"?registered\"]\n        - op: ne\n          args: [\"?expected\", \"?recorded\"]\n    - id: REGISTRY.RECORD.MISMATCH\n      head:\n        relation: recordMismatch\n        args: [\"?observation\", transport_registered, \"?expected\", \"?recorded\"]\n      body:\n        - relation: registryObservation\n          args: [\"?observation\", \"?scope\", \"?recorded\", \"?source\"]\n        - relation: stateDetails\n          args: [\"?state\", \"?scope\", \"?portal\", \"?expected\"]\n        - op: ne\n          args: [\"?expected\", \"?recorded\"]\n  admission:\n    - id: ONE.SHIPMENT.SCOPE\n      label: Review exactly one shipment scope\n      when:\n        - count:\n            relation: scope\n            args: [\"?id\", \"?order\", \"?revision\", \"?recipient\", \"?date\", \"?profile\", \"?point\"]\n          as: \"?scopes\"\n      assert:\n        op: eq\n        args: [\"?scopes\", 1]\n    - id: SOURCE.ALREADY.OBSERVED\n      label: The actual source record exists by the current review time\n      when:\n        - relation: source\n          args: [\"?source\", \"?scope\", \"?kind\", \"?at\", \"?description\"]\n      assert:\n        op: lte\n        args:\n          - \"?at\"\n          - parameter: currentTime\n    - id: portalObservation.SOURCE.SCOPE\n      label: The source record covers the same shipment claim\n      when:\n        - relation: portalObservation\n          args: [\"?id\", \"?scope\", \"?value\", \"?source\"]\n        - relation: source\n          args: [\"?source\", \"?sourceScope\", \"?kind\", \"?at\", \"?description\"]\n      assert:\n        op: eq\n        args: [\"?scope\", \"?sourceScope\"]\n    - id: portalObservation.SOURCE.KIND\n      label: Use the declared kind of actual source record\n      when:\n        - relation: portalObservation\n          args: [\"?id\", \"?scope\", \"?value\", \"?source\"]\n        - relation: source\n          args: [\"?source\", \"?sourceScope\", \"?kind\", \"?at\", \"?description\"]\n      assert:\n        op: eq\n        args: [\"?kind\", portal_capture]\n    - id: registryObservation.SOURCE.SCOPE\n      label: The source record covers the same shipment claim\n      when:\n        - relation: registryObservation\n          args: [\"?id\", \"?scope\", \"?value\", \"?source\"]\n        - relation: source\n          args: [\"?source\", \"?sourceScope\", \"?kind\", \"?at\", \"?description\"]\n      assert:\n        op: eq\n        args: [\"?scope\", \"?sourceScope\"]\n    - id: registryObservation.SOURCE.KIND\n      label: Use the declared kind of actual source record\n      when:\n        - relation: registryObservation\n          args: [\"?id\", \"?scope\", \"?value\", \"?source\"]\n        - relation: source\n          args: [\"?source\", \"?sourceScope\", \"?kind\", \"?at\", \"?description\"]\n      assert:\n        op: eq\n        args: [\"?kind\", actual_registry_report]\n  constraints:\n    - id: ALL.ACCEPTED.RECORDS.FIT\n      label: This possibility agrees with every reviewed record\n      when:\n        - count:\n            relation: recordMismatch\n            args: [\"?observation\", \"?field\", \"?expected\", \"?recorded\"]\n          as: \"?mismatches\"\n      assert:\n        op: eq\n        args: [\"?mismatches\", 0]\n  queries:\n    - id: transport-registration\n      label: \"Is the direct ship point transportation-registered for this shipment?\"\n      kind: boolean\n      body:\n        - relation: stateDetails\n          args: [\"?state\", \"?scope\", \"?portal\", true]\n    - id: transport-state\n      label: \"Which transportation state remains possible?\"\n      kind: value\n      body:\n        - relation: stateDetails\n          args: [\"?state\", \"?scope\", \"?portal\", \"?registered\"]\n      select: [\"?state\"]\n  reports:\n    tables:\n      - id: state-details\n        label: Transportation state in this explanation\n        relation: stateDetails\n        columns: [stateId, registered, portalListed, scope]\n      - id: portal-records\n        label: Reviewed portal listing records\n        relation: portalObservation\n        columns: [id, value, sourceId, scope]\n      - id: registry-records\n        label: Actual transportation registry reports\n        relation: registryObservation\n        columns: [id, value, sourceId, scope]\n      - id: conflicting-records\n        label: Records this possibility cannot explain\n        relation: recordMismatch\n        columns: [observation, field, expected, recorded]\n  presentation:\n    findingGroups:\n      - id: registration\n        title: Transportation registration\n        question: \"What do the records establish about this ship point?\"\n        description: Review the supported registration finding and the operating states still possible.\n        queryIds: [transport-registration, transport-state]\n    explanationGroups:\n      - id: transportation-state\n        title: Transportation state\n        question: \"Could the direct ship point support this shipment?\"\n        description: Each retained explanation represents an operating state compatible with the reviewed record.\n        items:\n          - kind: table\n            id: state-details\n      - id: reviewed-records\n        title: Reviewed records\n        question: \"Which actual records support or contradict this possibility?\"\n        description: Portal listings and registry reports establish different facts. A prospective report is absent from the evidence record.\n        items:\n          - kind: table\n            id: portal-records\n          - kind: table\n            id: registry-records\n          - kind: table\n            id: conflicting-records\ncase:\n  id: SHIP-104-EVIDENCE-r1\n  scope: ORD-104-r1-SP-A-2026-11-18-profile-1\n  parameters:\n    currentTime: 480\n  basis:\n    scope:\n      - id: ORD-104-r1-SP-A-2026-11-18-profile-1\n        orderId: ORD-104\n        orderRevision: \"1\"\n        recipient: DC-X\n        shipDate: \"2026-11-18\"\n        profileVersion: \"1.0.0\"\n        shipPoint: SP-A\n    source:\n      - id: PORTAL-CAPTURE-1\n        scope: ORD-104-r1-SP-A-2026-11-18-profile-1\n        kind: portal_ca