f: activity.release.end\n        startColumn: start\n        endColumn: end\n    - id: combined-resource-capacity\n      requirement: RESOURCES\n      kind: resource-capacity\n    - id: arrangement-selection-authority\n      requirement: AUTHORITY\n      kind: predicate\n      predicate:\n        op: exists\n        table: arrangementAuthorities\n        where:\n          arrangement:\n            ref: choice.arrangement\n          orderId:\n            ref: parameter.orderId\n          orderRevision:\n            ref: parameter.orderRevision\n          recipient:\n            ref: parameter.recipient\n          shipDate:\n            ref: parameter.shipDate\n          profileVersion:\n            ref: parameter.profileVersion\n        test:\n          op: and\n          args:\n            - op: lte\n              args:\n                - ref: row.start\n                - ref: parameter.actionReady\n            - op: gt\n              args:\n                - ref: row.end\n                - ref: parameter.actionReady\n    - id: scoped-final-release-grant\n      requirement: AUTHORITY\n      kind: predicate\n      predicate:\n        op: exists\n        table: grants\n        where:\n          actor:\n            ref: parameter.releaseActor\n          action:\n            literal: release\n          arrangement:\n            ref: choice.arrangement\n          shipPoint:\n            ref: derived.shipPoint\n          orderId:\n            ref: parameter.orderId\n          orderRevision:\n            ref: parameter.orderRevision\n          recipient:\n            ref: parameter.recipient\n          shipDate:\n            ref: parameter.shipDate\n          profileVersion:\n            ref: parameter.profileVersion\n        test:\n          op: and\n          args:\n            - op: lte\n              args:\n                - ref: row.start\n                - ref: activity.release.start\n            - op: gte\n              args:\n                - ref: row.end\n       